    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        long limit = Long.parseLong(st.nextToken());
        long window = Long.parseLong(st.nextToken());
        String[] names = new String[n], cities = new String[n];
        long[] times = new long[n], amounts = new long[n];
        for (int i = 0; i < n; i++) {
            names[i] = st.nextToken();
            times[i] = Long.parseLong(st.nextToken());
            amounts[i] = Long.parseLong(st.nextToken());
            cities[i] = st.nextToken();
        }
        List<Integer> res = findInvalid(names, times, amounts, cities, limit, window);
        StringBuilder sb = new StringBuilder();
        if (res.isEmpty()) sb.append("NONE");
        for (int i = 0; i < res.size(); i++) sb.append(res.get(i)).append(i + 1 < res.size() ? " " : "");
        System.out.println(sb);
    }
}
